import 'package:flutter/material.dart';
import '../services/api_service.dart';

class PeopleScreen extends StatefulWidget{final ApiService api; const PeopleScreen({super.key,required this.api});@override State<PeopleScreen> createState()=>_PeopleScreenState();}
class _PeopleScreenState extends State<PeopleScreen>{List<dynamic> contacts=[],invitations=[],users=[];String? msg;
  @override void initState(){super.initState();load();}
  Future<void> load()async{try{final a=await widget.api.contacts();final b=await widget.api.invitations();final c=await widget.api.users();if(mounted)setState((){contacts=a;invitations=b;users=c;});}catch(e){if(mounted)setState(()=>msg=e.toString());}}
  Future<void> add()async{final name=TextEditingController();final email=TextEditingController();await showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('Agregar contacto'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nombre')),TextField(controller:email,decoration:const InputDecoration(labelText:'Correo'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancelar')),FilledButton(onPressed:()async{await widget.api.addContact(name.text,email.text);if(ctx.mounted)Navigator.pop(ctx);await load();},child:const Text('Enviar invitación'))]));}
  Future<void> request(Map<String,dynamic> u)async{try{final r=await widget.api.requestWelfare(u['id'],'No he podido comunicarme con ${u['full_name']}');if(mounted)setState(()=>msg='Verificación solicitada: ${r['status']}');}catch(e){if(mounted)setState(()=>msg=e.toString());}}
  @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.fromLTRB(18,18,18,110),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Personas y círculo',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),IconButton(onPressed:add,icon:const Icon(Icons.person_add_alt_1))]),if(msg!=null)Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Text(msg!)),if(invitations.isNotEmpty)...[const Text('Invitaciones',style:TextStyle(fontWeight:FontWeight.w700)),...invitations.map((i)=>Card(child:ListTile(title:Text(i['contact_name']),subtitle:Text(i['contact_email']),trailing:Wrap(children:[IconButton(onPressed:()async{await widget.api.acceptInvitation(i['id'],true);load();},icon:const Icon(Icons.check,color:Colors.green)),IconButton(onPressed:()async{await widget.api.acceptInvitation(i['id'],false);load();},icon:const Icon(Icons.close,color:Colors.red))]))))],const SizedBox(height:8),const Text('Mi círculo de confianza',style:TextStyle(fontWeight:FontWeight.w700)),...contacts.map((c)=>Card(child:ListTile(leading:CircleAvatar(child:Text((c['contact_name']??'?').toString().substring(0,1))),title:Text(c['contact_name']),subtitle:Text('${c['status']} • ubicación: ${c['can_view_checkpoint']?'permitida':'restringida'}')))),const SizedBox(height:18),const Text('Solicitar verificación',style:TextStyle(fontWeight:FontWeight.w700)),...users.map((u)=>Card(child:ListTile(title:Text(u['full_name']),subtitle:Text(u['email']),trailing:TextButton(onPressed:()=>request(Map<String,dynamic>.from(u)),child:const Text('Verificar'))))]);
}
